arguments.command:
/root/.venv/bin/python - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
# find any cell with value 2018, 2019, 2020, 2021, 2022
years={2018,2019,2020,2021,2022,'2018','2019','2020','2021','2022'}
found=[]
for row in ws.iter_rows():
    for cell in row:
        v=cell.value
        if v in years:
            found.append((cell.coordinate, v))
if found:
    print('Found years:', found)
else:
    print('No year values found in Data sheet')

# find header-like row: for each row 1-40 count non-empty
for r in range(1,41):
    cnt=0
    for c in range(1,101):
        if ws.cell(r,c).value is not None:
            cnt+=1
    if cnt:
        print('Row', r, 'non-empty', cnt)
